import itertools
import json

def generate_perms(values, fixed_positions):
    # fixed_positions: dict value -> pos
    n = len(values)
    fixed_rev = {}
    for v, p in fixed_positions.items():
        if v not in values:
            return  # invalid fixed
        if p < 0 or p >= n:
            return
        if p in fixed_rev and fixed_rev[p] != v:
            return
        fixed_rev[p] = v
    remaining_values = [v for v in values if v not in fixed_positions]
    remaining_positions = [i for i in range(n) if i not in fixed_rev]
    for perm in itertools.permutations(remaining_values, len(remaining_values)):
        arr = [None] * n
        for p, v in fixed_rev.items():
            arr[p] = v
        for idx, p in enumerate(remaining_positions):
            arr[p] = perm[idx]
        yield arr

def solve():
    categories = ["Name", "Food", "CarModel", "PhoneModel", "Occupation", "Drink"]
    values = {
        "Name": ["Eric", "Peter", "Arnold", "Alice", "Bob"],
        "Food": ["stir fry", "spaghetti", "stew", "grilled cheese", "pizza"],
        "CarModel": ["ford f150", "tesla model 3", "bmw 3 series", "toyota camry", "honda civic"],
        "PhoneModel": ["iphone 13", "google pixel 6", "samsung galaxy s21", "oneplus 9", "huawei p50"],
        "Occupation": ["teacher", "lawyer", "doctor", "artist", "engineer"],
        "Drink": ["tea", "milk", "water", "root beer", "coffee"],
    }

    assignments = {cat: None for cat in categories}

    def pos(cat, val):
        arr = assignments.get(cat)
        if arr is None:
            return None
        try:
            return arr.index(val)
        except ValueError:
            return None

    def check_eq(cat1, val1, cat2, val2):
        i1 = pos(cat1, val1)
        i2 = pos(cat2, val2)
        if i1 is not None and i2 is not None:
            return i1 == i2
        return True

    def check_not_at(cat, val, idx):
        i = pos(cat, val)
        if i is not None and i == idx:
            return False
        return True

    def check_left_of_exact(catL, valL, catR, valR):
        iL = pos(catL, valL)
        iR = pos(catR, valR)
        if iL is not None and iR is not None:
            return iL + 1 == iR
        if iL is not None:
            if iL == 4:
                return False
        if iR is not None:
            if iR == 0:
                return False
        return True

    def check_left_of_somewhere(catLeft, valLeft, catRight, valRight):
        iL = pos(catLeft, valLeft)
        iR = pos(catRight, valRight)
        if iL is not None and iR is not None:
            return iL < iR
        if iL is not None and iL == 4:
            return False
        if iR is not None and iR == 0:
            return False
        return True

    def check_distance(cat1, val1, cat2, val2, dist):
        i1 = pos(cat1, val1)
        i2 = pos(cat2, val2)
        if i1 is not None and i2 is not None:
            return abs(i1 - i2) == dist
        return True

    def pos_doctor():
        # If Occupation assigned, use it; else use Arnold's position if known
        occ = assignments.get("Occupation")
        if occ is not None:
            return pos("Occupation", "doctor")
        return pos("Name", "Arnold")

    def check_all():
        # 1. The root beer lover is the person who owns a Honda Civic.
        if not check_eq("Drink", "root beer", "CarModel", "honda civic"):
            return False
        # 2. Milk directly left of grilled cheese.
        if not check_left_of_exact("Drink", "milk", "Food", "grilled cheese"):
            return False
        # 3. Alice uses a Samsung Galaxy S21.
        if not check_eq("Name", "Alice", "PhoneModel", "samsung galaxy s21"):
            return False
        # 4. Alice loves stir fry.
        if not check_eq("Name", "Alice", "Food", "stir fry"):
            return False
        # 5. Tea not in fifth house.
        if not check_not_at("Drink", "tea", 4):
            return False
        # 6. BMW somewhere left of tea.
        if not check_left_of_somewhere("CarModel", "bmw 3 series", "Drink", "tea"):
            return False
        # 7. Doctor is Arnold.
        if assignments["Occupation"] is not None and assignments["Name"] is not None:
            if not check_eq("Name", "Arnold", "Occupation", "doctor"):
                return False
        # 8. iPhone 13 user is the coffee drinker.
        if not check_eq("PhoneModel", "iphone 13", "Drink", "coffee"):
            return False
        # 9. Engineer owns BMW 3 Series.
        if assignments["Occupation"] is not None:
            if not check_eq("Occupation", "engineer", "CarModel", "bmw 3 series"):
                return False
        # 10. Stew lover uses an iPhone 13.
        if not check_eq("Food", "stew", "PhoneModel", "iphone 13"):
            return False
        # 11. Doctor is directly left of OnePlus 9.
        pDoc = pos_doctor()
        pOnePlus = pos("PhoneModel", "oneplus 9")
        if pDoc is not None and pOnePlus is not None:
            if pDoc + 1 != pOnePlus:
                return False
        elif pDoc is not None:
            if pDoc == 4:
                return False
        elif pOnePlus is not None:
            if pOnePlus == 0:
                return False
        # 12. Honda Civic is directly left of the spaghetti eater.
        if not check_left_of_exact("CarModel", "honda civic", "Food", "spaghetti"):
            return False
        # 13. Google Pixel 6 user is the tea drinker.
        if not check_eq("PhoneModel", "google pixel 6", "Drink", "tea"):
            return False
        # 14. Alice is an artist.
        if assignments["Occupation"] is not None and assignments["Name"] is not None:
            if not check_eq("Name", "Alice", "Occupation", "artist"):
                return False
        # 15. One house between Alice and the Ford F-150.
        if not check_distance("Name", "Alice", "CarModel", "ford f150", 2):
            return False
        # 16. Arnold owns a Toyota Camry.
        if not check_eq("Name", "Arnold", "CarModel", "toyota camry"):
            return False
        # 17. Eric is in the fourth house.
        pEric = pos("Name", "Eric")
        if pEric is not None and pEric != 3:
            return False
        if pEric is None:
            # If names not assigned yet, can't check
            pass
        # 18. OnePlus 9 user is a lawyer.
        if assignments["Occupation"] is not None:
            if not check_eq("PhoneModel", "oneplus 9", "Occupation", "lawyer"):
                return False
        # 19. Grilled cheese is Peter.
        if not check_eq("Food", "grilled cheese", "Name", "Peter"):
            return False

        # Additional early implication: From 2 and 19, Peter cannot be in the first house.
        pPeter = pos("Name", "Peter")
        if pPeter is not None and pPeter == 0:
            return False

        return True

    # Names
    for names in generate_perms(values["Name"], {"Eric": 3}):
        assignments["Name"] = names
        if not check_all():
            assignments["Name"] = None
            continue

        # Cars: fix Camry at Arnold, and filter Ford distance 2 from Alice
        pArnold = pos("Name", "Arnold")
        pAlice = pos("Name", "Alice")
        cars_fixed = {"toyota camry": pArnold}
        for cars in generate_perms(values["CarModel"], cars_fixed):
            assignments["CarModel"] = cars
            # Enforce Ford distance condition early
            pFord = pos("CarModel", "ford f150")
            if pFord is not None and abs(pFord - pAlice) != 2:
                assignments["CarModel"] = None
                continue
            if not check_all():
                assignments["CarModel"] = None
                continue

            # Phones: Samsung at Alice, OnePlus 9 at (Doctor+1) = (Arnold+1)
            pDoc = pos("Name", "Arnold")
            if pDoc == 4:
                assignments["CarModel"] = None
                continue  # impossible to have doc left of someone
            phones_fixed = {"samsung galaxy s21": pAlice, "oneplus 9": pDoc + 1}
            ok_phone_positions = True
            # ensure fixed positions are within bounds
            for v, p in phones_fixed.items():
                if p < 0 or p > 4:
                    ok_phone_positions = False
                    break
            if not ok_phone_positions:
                assignments["CarModel"] = None
                continue

            for phones in generate_perms(values["PhoneModel"], phones_fixed):
                assignments["PhoneModel"] = phones
                if not check_all():
                    assignments["PhoneModel"] = None
                    continue

                # Occupation: derive deterministically
                occ = [None] * 5
                # doctor = Arnold
                occ[pArnold] = "doctor"
                # artist = Alice
                occ[pAlice] = "artist"
                # lawyer = OnePlus 9 user
                pOnePlus = pos("PhoneModel", "oneplus 9")
                if occ[pOnePlus] is not None and occ[pOnePlus] != "lawyer":
                    assignments["PhoneModel"] = None
                    continue
                occ[pOnePlus] = "lawyer"
                # engineer = BMW 3 Series owner
                pBMW = pos("CarModel", "bmw 3 series")
                if occ[pBMW] is not None and occ[pBMW] != "engineer":
                    assignments["PhoneModel"] = None
                    continue
                occ[pBMW] = "engineer"
                # remaining = teacher
                remaining_positions = [i for i, v in enumerate(occ) if v is None]
                if len(remaining_positions) != 1:
                    assignments["PhoneModel"] = None
                    continue
                occ[remaining_positions[0]] = "teacher"
                assignments["Occupation"] = occ

                if not check_all():
                    assignments["Occupation"] = None
                    assignments["PhoneModel"] = None
                    continue

                # Drinks: tea at Pixel6, root beer at Honda, coffee at iPhone13, milk at Peter-1
                pPixel = pos("PhoneModel", "google pixel 6")
                pHonda = pos("CarModel", "honda civic")
                pIPhone = pos("PhoneModel", "iphone 13")
                pPeter = pos("Name", "Peter")
                fixed_drinks = {}
                if pPixel is None or pHonda is None or pIPhone is None or pPeter is None:
                    assignments["Occupation"] = None
                    assignments["PhoneModel"] = None
                    continue
                fixed_drinks["tea"] = pPixel
                fixed_drinks["root beer"] = pHonda
                fixed_drinks["coffee"] = pIPhone
                # milk position must be Peter-1
                if pPeter - 1 < 0:
                    assignments["Occupation"] = None
                    assignments["PhoneModel"] = None
                    continue
                fixed_drinks["milk"] = pPeter - 1

                # Ensure tea not at index 4
                if fixed_drinks.get("tea", None) == 4:
                    assignments["Occupation"] = None
                    assignments["PhoneModel"] = None
                    continue

                for drinks in generate_perms(values["Drink"], fixed_drinks):
                    assignments["Drink"] = drinks
                    if not check_all():
                        assignments["Drink"] = None
                        continue

                    # Food: grilled cheese at Peter, stir fry at Alice, stew at iPhone13, spaghetti at Honda+1
                    pHonda = pos("CarModel", "honda civic")
                    pPeter = pos("Name", "Peter")
                    pAlice = pos("Name", "Alice")
                    pIPhone = pos("PhoneModel", "iphone 13")
                    if pHonda is None or pPeter is None or pAlice is None or pIPhone is None:
                        assignments["Drink"] = None
                        continue
                    pSpaghetti = pHonda + 1
                    if pSpaghetti > 4:
                        assignments["Drink"] = None
                        continue
                    fixed_food = {
                        "grilled cheese": pPeter,
                        "stir fry": pAlice,
                        "stew": pIPhone,
                        "spaghetti": pSpaghetti
                    }

                    for foods in generate_perms(values["Food"], fixed_food):
                        assignments["Food"] = foods
                        if not check_all():
                            assignments["Food"] = None
                            continue

                        # Found solution
                        header = ["House", "Name", "Food", "CarModel", "PhoneModel", "Occupation", "Drink"]
                        rows = []
                        for i in range(5):
                            rows.append([
                                str(i + 1),
                                assignments["Name"][i],
                                assignments["Food"][i],
                                assignments["CarModel"][i],
                                assignments["PhoneModel"][i],
                                assignments["Occupation"][i],
                                assignments["Drink"][i],
                            ])
                        return {
                            "solution": {
                                "header": header,
                                "rows": rows
                            }
                        }

                    assignments["Food"] = None
                    assignments["Drink"] = None

                assignments["Occupation"] = None
                assignments["PhoneModel"] = None

            assignments["CarModel"] = None

        assignments["Name"] = None

    return None

def main():
    result = solve()
    if result is None:
        print(json.dumps({"solution": {"header": ["House", "Name", "Food", "CarModel", "PhoneModel", "Occupation", "Drink"], "rows": []}}))
    else:
        print(json.dumps(result))

if __name__ == "__main__":
    main()
